package studio.solocamera;
import android.graphics.*;
/** Bounded deterministic particles and a soft traveling sheen; no decoded effect video. */
final class EditorProfessionFx {
 private final EditorProject.Clip clip;private final Paint p=new Paint(3);private final int variant,secondary;private final float[] xs=new float[18],ys=new float[18],speeds=new float[18];
 EditorProfessionFx(EditorProject.Clip c){clip=c;int id=c.titleDesign-1;variant=EditorProfessionTitles.variant(id);secondary=EditorProfessionTitles.SECONDARY[EditorProfessionTitles.domain(id)];for(int i=0;i<18;i++){xs[i]=((i*47+17)%101)/101f;ys[i]=((i*31+23)%97)/97f;speeds[i]=.025f+i%4*.012f;}}
 void draw(Canvas c,int w,int h,long time,long duration){float in=Math.min(1,time/650f),out=Math.min(1,(duration-time)/450f),fade=Math.max(0,Math.min(in,out)),unit=w/928f;if(clip.titleGlow>0){float t=(time%3600)/3600f,edge=w*(-.20f+1.4f*t);p.setColor(EditorProfessionTitles.alpha(clip.designAccent,(int)(fade*clip.titleGlow*32)));for(int i=0;i<6;i++){float x=edge-i*unit*4;p.setAlpha((int)(fade*clip.titleGlow*(6-i)*4));c.drawRect(x,variant==4?h*.08f:h*.06f,x+unit*2,variant==4?h*.92f:h*.94f,p);}p.setAlpha(255);}if(!clip.titleParticles)return;for(int i=0;i<xs.length;i++){float x=(xs[i]+time*.000015f*(i%2==0?1:-1)+1)%1,y=(ys[i]-time*.001f*speeds[i]+10)%1;if(variant!=4&&x>.29f&&x<.90f&&y>.15f&&y<.84f)continue;float px=w*x,py=h*y,r=unit*(i%3==0?1.8f:1.0f),pulse=.45f+.55f*(float)Math.sin(time*.002f+i);int color=i%2==0?clip.designAccent:secondary;p.setColor(EditorProfessionTitles.alpha(color,(int)(fade*pulse*26)));c.drawCircle(px,py,r*3,p);p.setColor(EditorProfessionTitles.alpha(color,(int)(fade*pulse*170)));c.drawCircle(px,py,r,p);if(i%5==0){p.setStrokeWidth(Math.max(1,unit));c.drawLine(px-r*3,py,px+r*3,py,p);c.drawLine(px,py-r*3,px,py+r*3,p);}}}
}
